insert into public.indicator (id,org_id,framework_version_id,code,name,domain_code,domain_name,subdomain_code,subdomain_name,level_descriptors,look_fors,age_band) values
  ('301fc11a-f317-407c-a15d-04ec552cb223', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '1.1.1', 'Creating a Warm, Safe and Motivating Environment', '1', 'Building Trusting Relationships', '1.1', 'Engaging in Positive Interactions', '{"1":"Greets children warmly and keeps the space safe and calm.","2":"Adjusts tone, space and routines so each child feels welcome and wants to take part.","3":"Children help shape a caring space and look out for each other''s comfort and safety."}'::jsonb, '["Greets children by name with warmth","Calm, friendly tone of voice","Children move about confidently and seek out the educator"]'::jsonb, '2-6'),
  ('2b19cdc9-a3d4-4671-9816-257a255ec8e2', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '1.1.2', 'Facilitating Responsive Interactions', '1', 'Building Trusting Relationships', '1.1', 'Engaging in Positive Interactions', '{"1":"Notices and acknowledges children''s bids for attention.","2":"Responds promptly and in tune with each child''s cues and mood.","3":"Follows children''s lead and builds long, back-and-forth exchanges from their interests."}'::jsonb, '["Gets down to child''s eye level","Responds to a child''s bid within moments","Builds on what the child says or shows"]'::jsonb, '2-6'),
  ('350de283-6498-4925-a185-abd9442c5bd7', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '1.1.3', 'Facilitating Reciprocal Interactions', '1', 'Building Trusting Relationships', '1.1', 'Engaging in Positive Interactions', '{"1":"Takes turns in simple exchanges with children.","2":"Keeps conversations going with pauses that invite children to contribute.","3":"Children sustain multi-turn conversations with the educator and with each other."}'::jsonb, '["Waits for children to reply","Several turns on one topic","Invites a second child to join the exchange"]'::jsonb, '2-6'),
  ('1865af1a-846b-42b8-a52d-73c1be615257', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '1.1.4', 'Supporting Children Through Challenges', '1', 'Building Trusting Relationships', '1.1', 'Engaging in Positive Interactions', '{"1":"Comforts children who are upset and keeps them safe.","2":"Names the difficulty and offers a strategy to try.","3":"Coaches children to work through challenges themselves and support peers."}'::jsonb, '["Acknowledges the child''s feeling before redirecting","Offers a choice or strategy","Lets the child try again with support"]'::jsonb, '2-6'),
  ('30c26b42-3a37-48a1-846b-9b73105c0dee', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '1.1.5', 'Engaging in Inclusive and Respectful Interactions', '1', 'Building Trusting Relationships', '1.1', 'Engaging in Positive Interactions', '{"1":"Speaks respectfully to every child and avoids favouritism.","2":"Adapts interactions so every child, including quieter ones, is included.","3":"Children show respect and include one another without prompting."}'::jsonb, '["Uses each child''s name and preferred language","Draws quieter children into the activity","Responds to all children with equal warmth"]'::jsonb, '2-6'),
  ('d2bb28aa-c848-4ee5-91ee-169a6dd98646', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.1.1', 'Developing Values', '2', 'Nurturing Child Well-being', '2.1', 'Supporting Values Development', '{"1":"Names values such as kindness or honesty during routines.","2":"Plans moments that let children explore what a value looks like.","3":"Children discuss values and apply them to real situations in class."}'::jsonb, '["Talks about a value in context","Uses stories or role play to explore values","Asks children what a kind choice would be"]'::jsonb, '2-6'),
  ('53837231-ce21-4a26-8406-17fddd95ad65', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.1.2', 'Reinforcing Values', '2', 'Nurturing Child Well-being', '2.1', 'Supporting Values Development', '{"1":"Praises behaviour that shows a value.","2":"Gives specific feedback linking the action to the value.","3":"Children recognise and affirm values in each other''s actions."}'::jsonb, '["Specific praise naming the value","Links behaviour to its effect on others","Children notice kind acts by peers"]'::jsonb, '2-6'),
  ('ac636c70-e25c-42a9-b207-562dad8d493c', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.1.3', 'Encouraging Awareness, Respect and Celebration of Diversity', '2', 'Nurturing Child Well-being', '2.1', 'Supporting Values Development', '{"1":"Uses materials that show different cultures and families.","2":"Invites children to share and compare their own traditions.","3":"Children explore differences with curiosity and celebrate them together."}'::jsonb, '["Books and materials reflect diverse families","Invites children to share home languages or customs","Responds positively to questions about difference"]'::jsonb, '2-6'),
  ('0abed11c-fd7d-4751-bff4-530e9bf154ea', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.2.1', 'Helping Children Build Positive Self-Concept', '2', 'Nurturing Child Well-being', '2.2', 'Social and Emotional Competencies', '{"1":"Acknowledges children''s efforts and achievements.","2":"Highlights each child''s strengths and growth over time.","3":"Children describe their own strengths and set small goals."}'::jsonb, '["Praises effort, not only results","Displays children''s work with their words","Asks children what they are proud of"]'::jsonb, '2-6'),
  ('4247af91-2187-43c1-b9cc-ff85bec5733a', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.2.2', 'Helping Children Identify Emotions', '2', 'Nurturing Child Well-being', '2.2', 'Social and Emotional Competencies', '{"1":"Names emotions children show.","2":"Helps children notice body cues and name a wider range of feelings.","3":"Children name their own and others'' feelings in daily situations."}'::jsonb, '["Labels feelings as they happen","Uses emotion pictures or books","Asks ''how do you think he feels?''"]'::jsonb, '2-6'),
  ('d92c3011-7179-49b9-9618-7d47fd5e6d5b', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.2.3', 'Helping Children Express Emotions', '2', 'Nurturing Child Well-being', '2.2', 'Social and Emotional Competencies', '{"1":"Accepts children''s feelings without dismissing them.","2":"Offers safe ways to express feelings through words, art or movement.","3":"Children choose appropriate ways to express feelings on their own."}'::jsonb, '["Validates feelings (''it''s OK to feel sad'')","Provides a calm corner or expression tools","Models expressing own feelings"]'::jsonb, '2-6'),
  ('74f2a613-d78f-45b9-9868-f435af8658a5', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.2.4', 'Helping Children Self-Manage and Regulate Emotions', '2', 'Nurturing Child Well-being', '2.2', 'Social and Emotional Competencies', '{"1":"Calms children who are upset.","2":"Teaches simple calming strategies and prompts their use.","3":"Children use calming strategies independently and help peers."}'::jsonb, '["Teaches breathing or counting strategies","Prompts a strategy before stepping in","Children self-select calming activities"]'::jsonb, '2-6'),
  ('b124b112-8aec-428b-ad77-3474b6dd4408', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.2.5', 'Helping Children Identify and Respond to Emotions and Perspectives of Others', '2', 'Nurturing Child Well-being', '2.2', 'Social and Emotional Competencies', '{"1":"Points out how others might feel.","2":"Asks children to consider another''s view and how to respond.","3":"Children show empathy and respond to peers'' feelings unprompted."}'::jsonb, '["Asks ''how would you feel if…?''","Guides children to comfort a peer","Discusses characters'' feelings in stories"]'::jsonb, '2-6'),
  ('572cee2f-dc8e-4779-9538-0510a49fbb23', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.2.6', 'Encouraging Prosocial Behaviour', '2', 'Nurturing Child Well-being', '2.2', 'Social and Emotional Competencies', '{"1":"Encourages sharing and taking turns.","2":"Sets up activities that need cooperation and helping.","3":"Children cooperate, share and help without adult prompting."}'::jsonb, '["Plans partner or group tasks","Acknowledges helping behaviour","Children negotiate turns themselves"]'::jsonb, '2-6'),
  ('aacca0be-cd85-40af-aad1-6cdf9d819708', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.2.7', 'Promoting Social Awareness', '2', 'Nurturing Child Well-being', '2.2', 'Social and Emotional Competencies', '{"1":"Talks about people and roles in the community.","2":"Connects classroom life to families and the wider community.","3":"Children take part in projects that contribute to their community."}'::jsonb, '["Discusses community helpers","Invites family or community visitors","Children plan a way to help others"]'::jsonb, '2-6'),
  ('e1200c7b-504a-45ba-b43e-fdd6187dd6b1', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.3.1', 'Developing Perseverance', '2', 'Nurturing Child Well-being', '2.3', 'Fostering Learning Dispositions', '{"1":"Encourages children to keep trying.","2":"Breaks tasks into steps and celebrates persistence.","3":"Children take on challenges and keep going through setbacks."}'::jsonb, '["Says ''try another way'' rather than solving it","Names persistence when it happens","Offers appropriately challenging tasks"]'::jsonb, '2-6'),
  ('d1023b7b-d722-409e-85bf-9bb05608fd61', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.3.2', 'Fostering Reflectiveness', '2', 'Nurturing Child Well-being', '2.3', 'Fostering Learning Dispositions', '{"1":"Asks children what they did.","2":"Asks children how they did it and what they might change.","3":"Children review their own work and plan improvements."}'::jsonb, '["Asks ''what would you do differently?''","Holds short review times","Children revisit and revise their work"]'::jsonb, '2-6'),
  ('a9ebf248-058d-440a-8a30-e90b6305495d', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.3.3', 'Helping Children Appreciate Perspectives and Contributions of Others', '2', 'Nurturing Child Well-being', '2.3', 'Fostering Learning Dispositions', '{"1":"Lets children share ideas in turn.","2":"Highlights how different ideas help the group.","3":"Children build on each other''s ideas and credit peers."}'::jsonb, '["Invites several children to share ideas","Connects one child''s idea to another''s","Children say ''I like your idea because…''"]'::jsonb, '2-6'),
  ('c3071990-7548-4a07-8e5c-01cc5559d221', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.3.4', 'Encouraging Inventiveness', '2', 'Nurturing Child Well-being', '2.3', 'Fostering Learning Dispositions', '{"1":"Provides open-ended materials.","2":"Invites children to try new ways of using materials and ideas.","3":"Children design, invent and test their own creations."}'::jsonb, '["Open-ended materials available","Asks ''what else could this be?''","Children explain their inventions"]'::jsonb, '2-6'),
  ('e30179a7-b253-4904-9f9c-5357757da3d4', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.3.5', 'Promoting Sense of Curiosity', '2', 'Nurturing Child Well-being', '2.3', 'Fostering Learning Dispositions', '{"1":"Responds positively to children''s questions.","2":"Sets up provocations that spark wondering.","3":"Children pose their own questions and investigate them."}'::jsonb, '["Welcomes children''s questions","Introduces intriguing objects or problems","Children ask ''why'' and ''what if''"]'::jsonb, '2-6'),
  ('99666a9f-0e47-4e0a-81e3-3923ea7a4262', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '2.3.6', 'Promoting Engagement and Interest', '2', 'Nurturing Child Well-being', '2.3', 'Fostering Learning Dispositions', '{"1":"Gets children''s attention for activities.","2":"Builds activities around children''s interests to sustain engagement.","3":"Children stay deeply involved and extend activities themselves."}'::jsonb, '["Uses children''s interests in planning","Children stay on task for sustained periods","Children suggest next steps"]'::jsonb, '2-6'),
  ('2d05f2ae-87e5-4e3d-9ab8-17cd2deefbda', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.1.1', 'Making Connections Through an Integrated Approach', '3', 'Facilitating Learning and Development', '3.1', 'Planning Learning Environments and Experiences', '{"1":"Links an activity to one other learning area.","2":"Plans experiences that connect several learning areas around a theme.","3":"Children make their own connections across learning areas and to real life."}'::jsonb, '["Activity links two or more learning areas","Refers back to earlier learning","Children connect ideas to home or community"]'::jsonb, '2-6'),
  ('688cfecc-8901-45f2-93be-e350e0d3aacc', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.1.2', 'Catering to Diverse Learners', '3', 'Facilitating Learning and Development', '3.1', 'Planning Learning Environments and Experiences', '{"1":"Notices that children learn differently.","2":"Plans different entry points and supports for different learners.","3":"Children choose ways of learning that suit them."}'::jsonb, '["Offers materials at different levels","Adjusts support for individual children","Includes visual, verbal and hands-on options"]'::jsonb, '2-6'),
  ('0e3e76cb-ef12-4e12-b72d-4b9ee95ce3f7', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.1.3', 'Managing and Maximising Learning Opportunities', '3', 'Facilitating Learning and Development', '3.1', 'Planning Learning Environments and Experiences', '{"1":"Keeps routines running with little waiting time.","2":"Uses transitions and routines as chances to learn.","3":"Children manage routines themselves, freeing time for deeper learning."}'::jsonb, '["Minimal waiting during transitions","Learning talk during routines","Children know what to do next"]'::jsonb, '2-6'),
  ('65b9531f-f79f-4df6-bc5c-5d11c17e8eae', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.1.4', 'Providing Various Types of Learning Experiences', '3', 'Facilitating Learning and Development', '3.1', 'Planning Learning Environments and Experiences', '{"1":"Offers a mix of group and individual activities.","2":"Balances adult-guided and child-initiated experiences on purpose.","3":"Children move between experiences of their choice with purpose."}'::jsonb, '["Mix of whole-group, small-group and individual time","Indoor and outdoor experiences","Child-initiated play is planned for"]'::jsonb, '2-6'),
  ('5755c8ae-a3e5-46ae-8458-23f23cc48762', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.1.5', 'Establishing Clear Expectations and Guiding Proactively', '3', 'Facilitating Learning and Development', '3.1', 'Planning Learning Environments and Experiences', '{"1":"States rules simply and reminds children of them.","2":"Sets expectations with reasons and guides before problems arise.","3":"Children help set expectations and remind each other."}'::jsonb, '["Explains the reason behind a rule","Prepares children before transitions","Children co-create class agreements"]'::jsonb, '2-6'),
  ('d0c7e262-aa3f-4c57-a717-37231cb18989', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.1.6', 'Modifying Instruction to Meet Children''s Needs', '3', 'Facilitating Learning and Development', '3.1', 'Planning Learning Environments and Experiences', '{"1":"Repeats or simplifies when children are unsure.","2":"Changes pace, materials or grouping in the moment based on responses.","3":"Children''s responses and ideas visibly change the direction of the lesson."}'::jsonb, '["Checks understanding during the activity","Changes approach when children lose interest","Follows a child''s idea into the next step"]'::jsonb, '2-6'),
  ('f3e3f732-0e20-42d5-ad16-e28f3e006d4f', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.2.1', 'Exercising Flexibility in Catering to Children''s Needs and Interests', '3', 'Facilitating Learning and Development', '3.2', 'Child-Centric Practices and Play', '{"1":"Allows small changes to plans when children ask.","2":"Adapts plans around children''s emerging interests.","3":"Children''s interests drive extended projects."}'::jsonb, '["Adjusts the plan to an emerging interest","Extends time when engagement is high","Children''s ideas appear in planning"]'::jsonb, '2-6'),
  ('952bcd10-55c3-4c1f-bcec-9e047fd30321', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.2.2', 'Empowering Children''s Independence', '3', 'Facilitating Learning and Development', '3.2', 'Child-Centric Practices and Play', '{"1":"Lets children do simple tasks for themselves.","2":"Sets up the space and routines so children can manage on their own.","3":"Children take charge of tasks and support others'' independence."}'::jsonb, '["Materials within children''s reach","Waits before stepping in to help","Children self-serve and tidy up"]'::jsonb, '2-6'),
  ('f36fb29e-83a2-4206-9009-f2b5d508d484', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.2.3', 'Encouraging Children to Make Choices and Decisions', '3', 'Facilitating Learning and Development', '3.2', 'Child-Centric Practices and Play', '{"1":"Offers simple choices between two options.","2":"Gives meaningful choices and talks through decisions.","3":"Children make and justify group and individual decisions."}'::jsonb, '["Offers real choices","Asks children to explain their choice","Children vote or agree on group decisions"]'::jsonb, '2-6'),
  ('5d24d10a-a243-4c4f-bb9c-544b03870c0b', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.2.4', 'Providing Children Opportunities to Lead and Take on Roles', '3', 'Facilitating Learning and Development', '3.2', 'Child-Centric Practices and Play', '{"1":"Assigns simple helper roles.","2":"Rotates leadership roles and coaches children in them.","3":"Children lead activities and take on roles they design."}'::jsonb, '["Rotating class helper roles","Children lead a part of an activity","Children teach or show peers"]'::jsonb, '2-6'),
  ('5c0f6b4a-171e-4272-b639-d8c795b6249e', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.2.5', 'Engaging Children Through a Variety of Play', '3', 'Facilitating Learning and Development', '3.2', 'Child-Centric Practices and Play', '{"1":"Provides time and materials for play.","2":"Joins play to extend it without taking over.","3":"Children sustain complex play with rich roles and ideas."}'::jsonb, '["Variety of play types (pretend, construction, physical)","Educator joins play as a co-player","Extended, complex play scenarios"]'::jsonb, '2-6'),
  ('5aafae69-9107-4e0d-b80c-e9bad5749718', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.2.6', 'Catering to Children''s Level of Engagement', '3', 'Facilitating Learning and Development', '3.2', 'Child-Centric Practices and Play', '{"1":"Notices when children are disengaged.","2":"Adjusts challenge or support to re-engage individual children.","3":"Children self-regulate their engagement and choose challenges."}'::jsonb, '["Notices and responds to disengagement","Offers extensions for children who finish early","Children choose harder levels themselves"]'::jsonb, '2-6'),
  ('562a7947-5e5a-425b-841d-76e52898b828', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.3.1', 'Encouraging the Use of Language', '3', 'Facilitating Learning and Development', '3.3', 'Extending Thinking, Language and Learning', '{"1":"Talks with children throughout the day.","2":"Models and introduces new words in context.","3":"Children use rich and new vocabulary in their own talk."}'::jsonb, '["Describes actions aloud","Introduces new words with meaning","Children use new words"]'::jsonb, '2-6'),
  ('9af0001e-c714-46d0-a932-203e669c8c3a', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.3.2', 'Extending the Use of Language Through Print', '3', 'Facilitating Learning and Development', '3.3', 'Extending Thinking, Language and Learning', '{"1":"Points out print in the environment.","2":"Uses print purposefully with children, such as labels, lists and stories.","3":"Children create and use print for their own purposes."}'::jsonb, '["Labels and print at child height","Writes children''s words down","Children make signs, lists or books"]'::jsonb, '2-6'),
  ('a4da604e-a286-4f15-8379-a92e1b1e1e55', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.3.3', 'Encouraging Communication and Conversations', '3', 'Facilitating Learning and Development', '3.3', 'Extending Thinking, Language and Learning', '{"1":"Invites children to talk about their experiences.","2":"Sets up pair and small-group talk.","3":"Children hold sustained conversations with peers."}'::jsonb, '["Uses ''turn and talk''","Small-group conversations","Children respond to each other, not only the adult"]'::jsonb, '2-6'),
  ('cc316941-40f5-4fb8-90bf-1ee33d7ff818', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.3.4', 'Extending Thinking Through Questioning', '3', 'Facilitating Learning and Development', '3.3', 'Extending Thinking, Language and Learning', '{"1":"Asks questions, mostly closed or recall questions.","2":"Asks open questions and waits for children to think.","3":"Uses follow-up questions to deepen thinking, and children ask each other questions."}'::jsonb, '["Asks open ''why'' and ''how'' questions","Waits at least 3 seconds after asking","Follows up with ''what makes you think that?''"]'::jsonb, '2-6'),
  ('e5dcf3bf-6311-4e01-9304-edc03a571de3', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.3.5', 'Providing Support to Deepen Thinking', '3', 'Facilitating Learning and Development', '3.3', 'Extending Thinking, Language and Learning', '{"1":"Gives hints when children are stuck.","2":"Scaffolds with prompts, models and materials.","3":"Children reason aloud and test ideas with light support."}'::jsonb, '["Scaffolds instead of giving the answer","Models thinking aloud","Children explain their reasoning"]'::jsonb, '2-6'),
  ('472b22e7-cb3e-44cc-8bb4-8659b4c8c167', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.3.6', 'Providing Feedback That Extends Understanding and Deepens Thinking', '3', 'Facilitating Learning and Development', '3.3', 'Extending Thinking, Language and Learning', '{"1":"Gives general praise such as ''good job''.","2":"Gives specific feedback about what the child did.","3":"Gives feedback that prompts the child to think further and improve."}'::jsonb, '["Specific, descriptive feedback","Feedback ends with a question or next step","Children act on the feedback"]'::jsonb, '2-6'),
  ('d016f966-f924-4723-9484-8acdc54a61db', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.3.7', 'Providing Problem Solving Opportunities', '3', 'Facilitating Learning and Development', '3.3', 'Extending Thinking, Language and Learning', '{"1":"Presents simple problems with one answer.","2":"Sets open problems with more than one solution.","3":"Children identify problems themselves and plan solutions."}'::jsonb, '["Poses real, open problems","Accepts more than one solution","Children identify problems to solve"]'::jsonb, '2-6'),
  ('94d2b479-6ec3-4b8e-af60-f72faca15835', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.3.8', 'Engaging Children in Problem Solving', '3', 'Facilitating Learning and Development', '3.3', 'Extending Thinking, Language and Learning', '{"1":"Solves problems with children step by step.","2":"Guides children to try, check and change their approach.","3":"Children solve problems together and explain their strategies."}'::jsonb, '["Asks children to predict and test","Encourages trying a different strategy","Children work together on a solution"]'::jsonb, '2-6'),
  ('891f63d6-7397-40dc-a4eb-d36f0415ed21', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.4.1', 'Facilitating Self-Management Skills', '3', 'Facilitating Learning and Development', '3.4', 'Self-Regulation and Executive Function', '{"1":"Reminds children of routines and steps.","2":"Uses visual schedules and checklists children can follow.","3":"Children manage their own belongings, time and tasks."}'::jsonb, '["Visual schedule in use","Children follow steps without reminders","Children manage their own materials"]'::jsonb, '2-6'),
  ('55c2fe7f-2dbc-4741-bfe7-8a409957e553', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.4.2', 'Facilitating Self-Regulation Skills', '3', 'Facilitating Learning and Development', '3.4', 'Self-Regulation and Executive Function', '{"1":"Tells children to wait or stop.","2":"Uses games and strategies that practise waiting and impulse control.","3":"Children regulate their behaviour and help peers do so."}'::jsonb, '["Uses stop–go or turn-taking games","Gives a strategy before a waiting time","Children remind each other of agreements"]'::jsonb, '2-6'),
  ('0a620882-7599-4c92-9d44-036ba7e6067f', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.4.3', 'Facilitating Working Memory', '3', 'Facilitating Learning and Development', '3.4', 'Self-Regulation and Executive Function', '{"1":"Gives one instruction at a time.","2":"Plays games that ask children to remember and use information.","3":"Children hold multi-step plans in mind and carry them out."}'::jsonb, '["Memory games or recall activities","Multi-step instructions with support","Children retell sequences"]'::jsonb, '2-6'),
  ('299932f7-d548-4b5a-b0c5-17c14dada49f', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.4.4', 'Developing Cognitive Flexibility', '3', 'Facilitating Learning and Development', '3.4', 'Self-Regulation and Executive Function', '{"1":"Shows that there can be more than one way.","2":"Asks children to switch rules or think of alternatives.","3":"Children shift strategies and see others'' viewpoints easily."}'::jsonb, '["Games with changing rules","Asks ''what''s another way?''","Children adapt when plans change"]'::jsonb, '2-6'),
  ('9c10294a-91f6-43e5-be43-a3c681a44cb9', null, '45dd87b9-d798-42a9-96ad-fb9c85cd0181', '3.4.5', 'Guiding Children in Planning and Organising to Achieve a Goal', '3', 'Facilitating Learning and Development', '3.4', 'Self-Regulation and Executive Function', '{"1":"Tells children the plan for an activity.","2":"Helps children make a simple plan and check progress.","3":"Children set goals, plan steps and review their own progress."}'::jsonb, '["Plan–do–review routine","Children draw or say their plan","Children check progress against their plan"]'::jsonb, '2-6'),
